#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> p(n);
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
        sum += p[i];
    }

    int target = sum / n;

    for (int i = 0; i < n; ++i) {
        cout << target - p[i] << "\n";
    }

    return 0;
}
